    "in the root folder. The markdown file is where your ideas\n"
    "will be stored.\n"
    "\n"
    "Once first time setup has completed, simply run Eureka again\n"
    "to begin writing down ideas.\n"
    "        \n"
)


class ConfigError(Exception):
    pass


def prog_name() -> str:
    base = os.path.basename(sys.argv[0])
    return base or "executable"


def help_text(name: Optional[str] = None) -> str:
    n = name if name is not None else prog_name()
    return (
        f"{ABOUT}\n\n"
        f"Usage: {n} [OPTIONS]\n\n"
        "Options:\n"
        "      --clear-config  Clear your stored configuration\n"
        "  -v, --view          View ideas with your $PAGER env variable. If unset use less\n"
        "  -h, --help          Print help\n"
        "  -V, --version       Print version\n"
    )


def write_out(s: str) -> None:
    sys.stdout.write(s)
    sys.stdout.flush()


def log_error(msg: str) -> None:
    sys.stderr.write(f" ERROR eureka > {msg}\n")
    sys.stderr.flush()


def os_error_message(exc: BaseException) -> str:
    if isinstance(exc, FileNotFoundError):
        return "No such file or directory (os error 2)"
    if isinstance(exc, PermissionError):
        return "Permission denied (os error 13)"
    if isinstance(exc, OSError):
        if exc.errno is not None and exc.strerror:
            return f"{exc.strerror} (os error {exc.errno})"
        return str(exc)
    return str(exc)


def config_path() -> str:
    # The observed executable honors XDG_CONFIG_HOME if it is present, even if
    # it is an empty or relative string. Otherwise it falls back to ~/.config.
    if "XDG_CONFIG_HOME" in os.environ:
        base = os.environ.get("XDG_CONFIG_HOME", "")
    else:
        home = os.environ.get("HOME")
        if home is None:
            base = os.path.join(os.path.expanduser("~"), ".config")
        else:
            base = os.path.join(home, ".config")
    return os.path.join(base, "eureka", "config.json")


def serde_json_decode_message(text: str, err: json.JSONDecodeError) -> str:
    # Match the Rust/serde_json style for the common malformed configs that are
    # likely to be encountered. This is intentionally best-effort; valid configs
    # are the important path.
    stripped = text.strip()
    if stripped == "":
        return "No such file or directory (os error 2)"
    if stripped == "[":
        return "EOF while parsing a list at line 1 column 1"
    if stripped == "{":
        return "EOF while parsing an object at line 1 column 1"
    if stripped.startswith("{") and not stripped.endswith("}"):
        # serde reports the last consumed column for an unterminated object.
        return f"EOF while parsing an object at line 1 column {max(1, len(stripped))}"
    if stripped.startswith("[") and not stripped.endswith("]"):
        return f"EOF while parsing a list at line 1 column {max(1, len(stripped))}"
    # A bare word such as "not json" is reported by serde as an identifier
    # parsing failure.
    if stripped and (stripped[0].isalpha() or stripped[0] == "_"):
        return f"expected ident at line {err.lineno} column {err.colno}"
    return f"{err.msg} at line {err.lineno} column {err.colno}"


def serde_type_name(value) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return f"boolean `{str(value).lower()}`"
    if isinstance(value, int) and not isinstance(value, bool):
        return f"integer `{value}`"
    if isinstance(value, float):
        return f"floating point `{value}`"
    if isinstance(value, list):
        return "sequence"
    if isinstance(value, dict):
        return "map"
    return type(value).__name__


def load_config() -> str:
    path = config_path()
    try:
        with open(path, "r", encoding="utf-8") as f:
            text = f.read()
    except OSError as exc:
        raise ConfigError(os_error_message(exc))
    if text == "":
        raise ConfigError("No such file or directory (os error 2)")
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ConfigError(serde_json_decode_message(text, exc))
    if not isinstance(data, dict):
        raise ConfigError("invalid type: sequence, expected struct Config at line 1 column 0")
    if "repo" not in data:
        raise ConfigError("missing field `repo` at line 1 column 2")
    repo = data["repo"]
    if not isinstance(repo, str):
        # Column values are only approximate for unusual spacing, but exact for
        # the compact JSON produced by this program and common manual edits.
        col = text.find("repo")
        if col >= 0:
            val_start = text.find(":", col)
            column = val_start + 2 if val_start >= 0 else len(text)
        else:
            column = len(text)
        raise ConfigError(
            f"invalid type: {serde_type_name(repo)}, expected path string at line 1 column {max(1, column)}"
        )
    return repo


def save_config(repo: str) -> None:
    path = config_path()
    parent = os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)
    payload = json.dumps({"repo": repo}, ensure_ascii=False, separators=(",", ":"))
    with open(path, "w", encoding="utf-8") as f:
        f.write(payload)


def prompt(label: str, require_absolute: bool = False) -> str:
    while True:
        write_out(f"{RESET}{GREEN_BOLD}{label}\n{RESET}> ")
        line = sys.stdin.readline()
        if line == "":
            value = ""
        else:
            value = line.strip()
        if value == "":
            continue
        if require_absolute and not value.startswith(os.sep):
            write_out(f"{RESET}{RED}Path must be absolute\n{RESET}")
            continue
        return value


def first_time_setup() -> None:
    write_out(f"{RESET}{YELLOW}{SETUP_TEXT}{RESET}")
    repo = prompt("Absolute path to your idea repo", require_absolute=True)
    try:
        save_config(repo)
        write_out("First time setup complete. Happy ideation!\n")
    except OSError as exc:
        log_error(os_error_message(exc))


def clear_config() -> None:
    try:
        os.remove(config_path())
    except OSError as exc:
        log_error(os_error_message(exc))


def run_child(argv, *, capture: bool = False) -> subprocess.CompletedProcess:
    if capture:
        return subprocess.run(argv, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    return subprocess.run(argv)


def view_ideas() -> None:
    try:
        repo = load_config()
    except ConfigError as exc:
        log_error(str(exc))
        return
    readme = os.path.join(repo, "README.md")
    try:
        # The observed program checks that the file is readable before spawning
        # the pager; a missing README does not invoke $PAGER.
        with open(readme, "rb"):
            pass
    except OSError as exc:
        log_error(os_error_message(exc))
        return
    pager = os.environ.get("PAGER") if "PAGER" in os.environ else "less"
    try:
        subprocess.run([pager, readme])
    except OSError as exc:
        log_error(os_error_message(exc))


def git_capture(repo: str, *args: str) -> subprocess.CompletedProcess:
    return subprocess.run(
        ["git", "-C", repo, *args],
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )


def git_ok(repo: str, *args: str) -> bool:
    return git_capture(repo, *args).returncode == 0


def current_branch_ref(repo: str) -> str:
    cp = git_capture(repo, "symbolic-ref", "-q", "HEAD")
    if cp.returncode == 0:
        return cp.stdout.strip() or "refs/heads/master"
    return "refs/heads/master"


def open_repository_error(repo: str) -> Optional[str]:
    if not os.path.exists(repo):
        return f"failed to resolve path '{repo}': No such file or directory; class=Os (2); code=NotFound (-3)"
    cp = git_capture(repo, "rev-parse", "--git-dir")
    if cp.returncode != 0:
        return f"could not find repository from '{repo}'; class=Repository (6); code=NotFound (-3)"
    return None


def checkout_main(repo: str) -> Tuple[bool, Optional[str]]:
    # libgit2 reports an unborn current branch before it can create/switch main.
    if not git_ok(repo, "rev-parse", "--verify", "HEAD"):
        return (
            False,
            f"reference '{current_branch_ref(repo)}' not found; class=Reference (4); code=UnbornBranch (-9)",
        )

    main_exists = git_ok(repo, "show-ref", "--verify", "--quiet", "refs/heads/main")
    if not main_exists:
        cp = git_capture(repo, "branch", "main")
        if cp.returncode != 0:
            msg = (cp.stderr or cp.stdout).strip() or "could not create branch main"
            return False, msg

    cp = git_capture(repo, "checkout", "-q", "main")
    if cp.returncode != 0:
        combined = (cp.stderr or cp.stdout).strip()
        if "would be overwritten" in combined or "Please commit" in combined or "conflict" in combined.lower():
            return False, "1 conflict prevents checkout; class=Checkout (20); code=Conflict (-13)"
        return False, combined or "failed to checkout main"
    return True, None


def git_config_value(repo: str, key: str) -> Optional[str]:
    cp = git_capture(repo, "config", "--get", key)
    if cp.returncode == 0:
        return cp.stdout.rstrip("\n")
    return None


def add_and_commit(repo: str, readme: str, summary: str) -> bool:
    if not os.path.exists(readme):
        log_error(f"could not find '{readme}' to stat: No such file or directory; class=Os (2); code=NotFound (-3)")
        return False

    cp = git_capture(repo, "add", "--", "README.md")
    if cp.returncode != 0:
        msg = (cp.stderr or cp.stdout).strip() or "No such file or directory (os error 2)"
        log_error(msg)
        return False

    if git_config_value(repo, "user.name") is None:
        log_error("config value 'user.name' was not found; class=Config (7); code=NotFound (-3)")
        return False
    if git_config_value(repo, "user.email") is None:
        log_error("config value 'user.email' was not found; class=Config (7); code=NotFound (-3)")
        return False

    cp = git_capture(
        repo,
        "-c",
        "commit.gpgsign=false",
        "commit",
        "--allow-empty",
        "--no-verify",
        "-q",
        "-m",
        summary,
    )
    if cp.returncode != 0:
        msg = (cp.stderr or cp.stdout).strip() or "failed to commit"
        log_error(msg)
        return False
    write_out("Added and committed!\n")
    return True


def push_main(repo: str) -> bool:
    # Match the common libgit2 no-origin error exactly.
    if git_capture(repo, "remote", "get-url", "origin").returncode != 0:
        log_error("remote 'origin' does not exist; class=Config (7); code=NotFound (-3)")
        return False
    cp = git_capture(repo, "push", "-q", "origin", "main")
    if cp.returncode != 0:
        msg = (cp.stderr or cp.stdout).strip() or "failed to push"
        # Trim git's common leading "error:" noise less aggressively than the
        # original; retaining the useful message is better for users.
        log_error(msg)
        return False
    write_out("Pushed!\n")
    return True


def run_editor(readme: str) -> Tuple[Optional[str], bool]:
    """Run the editor.

    Returns (error_message, hard_error).  A hard edit error is one that the
    observed program reports before committing (notably an absent README).  A
    missing editor binary is reported after the empty commit/status messages.
    """
    if not os.path.exists(readme):
        return "No such file or directory (os error 2)", True
    if "EDITOR" not in os.environ:
        return "cannot find binary path", False
    editor = os.environ.get("EDITOR", "")
    try:
        subprocess.run([editor, readme])
    except OSError as exc:
        return os_error_message(exc), False
    return None, False


def capture_idea() -> None:
    try:
        repo = load_config()
    except ConfigError:
        first_time_setup()
        return

    summary = prompt(">> Idea summary")

    err = open_repository_error(repo)
    if err is not None:
        log_error(err)
        return

    readme = os.path.join(repo, "README.md")
    edit_error, hard_edit_error = run_editor(readme)

    write_out("Adding and committing your new idea to main..\n")

    ok, checkout_error = checkout_main(repo)
    if not ok:
        log_error(checkout_error or "failed to checkout main")
        return

    if hard_edit_error:
        log_error(edit_error or "No such file or directory (os error 2)")
        return

    if not add_and_commit(repo, readme, summary):
        return

    write_out("Pushing your new idea..\n")

    # For editor-spawn errors the observed binary has already created the empty
    # commit and printed the push prelude, then reports the editor error instead
    # of attempting/reporting the missing remote.
    if edit_error is not None:
        log_error(edit_error)
        return

    push_main(repo)


def usage_for_option(name: str) -> str:
    return f"Usage: {prog_name()} {name}\n"


def parse_error_unexpected_value(opt: str, val: str) -> int:
    sys.stderr.write(
        f"error: unexpected value '{val}' for '{opt}' found; no more were expected\n\n"
        f"{usage_for_option(opt)}\n"
        "For more information, try '--help'.\n"
    )
    return 2


def suggestion_for(arg: str) -> Optional[str]:
    opts = ["--clear-config", "--view", "--help", "--version"]
    matches = difflib.get_close_matches(arg, opts, n=1, cutoff=0.55)
    return matches[0] if matches else None


def parse_error_unexpected(arg: str) -> int:
    sug = suggestion_for(arg) if arg.startswith("--") else None
    sys.stderr.write(f"error: unexpected argument '{arg}' found\n")
    if sug:
        sys.stderr.write(f"\n  tip: a similar argument exists: '{sug}'\n\n")
        sys.stderr.write(usage_for_option(sug))
    else:
        sys.stderr.write(f"\nUsage: {prog_name()} [OPTIONS]\n")
    sys.stderr.write("\nFor more information, try '--help'.\n")
    return 2


def parse_error_duplicate_view() -> int:
    sys.stderr.write(
        "error: the argument '--view' cannot be used multiple times\n\n"
        f"Usage: {prog_name()} [OPTIONS]\n\n"
        "For more information, try '--help'.\n"
    )
    return 2


def action_from_first_arg(argv) -> Tuple[str, Optional[int]]:
    """Return (action, exit_code_if_parse_error).

    The observed clap setup effectively short-circuits on the first complete
    option token. Later tokens are ignored once an action token has parsed.
    """
    if not argv:
        return "capture", None
    arg = argv[0]
    if arg == "--":
        return "capture", None

    long_actions = {
        "--clear-config": "clear",
        "--view": "view",
        "--help": "help",
        "--version": "version",
    }
    if arg.startswith("--"):
        if "=" in arg:
            opt, val = arg.split("=", 1)
            if opt in long_actions:
                return "error", parse_error_unexpected_value(opt, val)
            return "error", parse_error_unexpected(arg)
        if arg in long_actions:
            return long_actions[arg], None
        return "error", parse_error_unexpected(arg)

    if arg.startswith("-") and arg != "-":
        seen_v = 0
        for ch in arg[1:]:
            if ch == "v":
                seen_v += 1
                if seen_v > 1:
                    return "error", parse_error_duplicate_view()
                continue
            if ch == "h":
                return "help", None
            if ch == "V":
                return "version", None
            # clap reports the individual short flag as the unexpected argument.
            return "error", parse_error_unexpected("-" + ch)
        if seen_v == 1:
            return "view", None
        return "capture", None

    return "error", parse_error_unexpected(arg)


def main() -> int:
    action, err_code = action_from_first_arg(sys.argv[1:])
    if action == "error":
        return int(err_code or 2)
    if action == "help":
        write_out(help_text())
        return 0
    if action == "version":
        write_out(VERSION)
        return 0
    if action == "view":
        view_ideas()
        return 0
    if action == "clear":
        clear_config()
        return 0
    capture_idea()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
